function onlinePvp(){return game?.mode==='coop'&&game.online!=='coop';}
function hostileRemotes(){return game?.mode==='squad104'?coopTargets().filter(r=>r.team!==game.myTeam):onlinePvp()?coopTargets().filter(r=>r.team!==game.myTeam&&!r.prot):[];}
