function weaponPose(){const eye=[game.p.x,eyeHeight(),game.p.z],f=direction(),right=[Math.cos(yaw),0,Math.sin(yaw)],up=cross(right,f),aim=game.ads||0,kick=game.kick||0,w=WEAPONS[game.weapon],progress=game.reload>0?1-game.reload/w.reload:0,drop=Math.sin(progress*Math.PI),sway=Math.sin(game.time*8)*(game.walk||0)*(1-aim)*.009,forward=norm(f.map((v,i)=>v+up[i]*(kick*1.15-drop*.32))),gunUp=cross(right,forward),root=I();const origin=eye.map((v,i)=>v+f[i]*(.57-kick*.85)+right[i]*(.205*(1-aim)+sway)-up[i]*(.185*(1-aim)+.105*aim+drop*.23));for(let i=0;i<3;i++){root[i]=right[i];root[i+4]=gunUp[i];root[i+8]=-forward[i];root[i+12]=origin[i];}const barrel=game.weapon==='smg'?.43:game.weapon==='sniper'?.84:game.weapon==='shotgun'?.67:.65;return{root,barrel,drop,progress,muzzle:origin.map((v,i)=>v+forward[i]*barrel)};}

function characterRoot(x,z,heading,hero=false,bob=0,y=0,prone=false){const root=model(x,hero?(game?.p.y||0):y,z,SOLDIER_SCALE,SOLDIER_SCALE,SOLDIER_SCALE,-heading);if((hero&&game?.prone)||prone){const pose=I();pose[5]=0;pose[6]=-1;pose[9]=.35;pose[10]=0;pose[13]=.34;pose[14]=.88;return mul(root,pose);}root[13]+=bob;return root;}
function cameraState(){const head=[game.p.x,eyeHeight(),game.p.z],f=direction();if(viewMode==='fps')return{eye:head,dir:f};const back=game.driving?8:zoom?2.1:4.2,right=[Math.cos(yaw),0,Math.sin(yaw)],desired=head.map((v,i)=>v-f[i]*back+right[i]*.65+(i===1?.5:0));const delta=desired.map((v,i)=>v-head[i]),len=Math.hypot(...delta),away=delta.map(v=>v/len),clear=obstruction(head,away),camDistance=Math.max(.12,Math.min(len,clear-.25)),eye=head.map((v,i)=>v+away[i]*camDistance),target=head.map((v,i)=>v+f[i]*35);return{eye,dir:norm(target.map((v,i)=>v-eye[i]))};}
function solid(x,z,r=.38,height=1.8,base=.1){for(const v of [...(game?.vehicles||[]),...(game?.ambulance?[game.ambulance]:[])]){if(v===game?.activeVehicle)continue;const spec=window.AkrivaIndia?.types[v.type]||{w:2.05,l:4.4,h:2.3},dx=x-v.x,dz=z-v.z,c=Math.cos(v.heading),n=Math.sin(v.heading);if(base<spec.h&&Math.abs(dx*c+dz*n)<spec.w/2+r&&Math.abs(-dx*n+dz*c)<spec.l/2+r)return true;}if(indiaWorld()){const india=window.AkrivaIndia;return Math.abs(x)>india.half||Math.abs(z)>india.half||[[0,0],[r,0],[-r,0],[0,r],[0,-r]].some(([dx,dz])=>!india.land(x+dx,z+dz))||india.blocks.some(b=>Math.abs(x-b.x)<b.w/2+r&&Math.abs(z-b.z)<b.d/2+r);}if(Math.abs(x)>WORLD.half||Math.abs(z)>WORLD.half)return true;for(const a of covers){const b=a.bounds||a;if(Math.abs(x-b.x)>b.w/2+r+.2||Math.abs(z-b.z)>b.d/2+r+.2)continue;const parts=a.parts||[a];if(parts.some(p=>(p.y||0)<height&&(p.y||0)+p.h>base&&Math.abs(x-p.x)<p.w/2+r&&Math.abs(z-p.z)<p.d/2+r))return true;}return false;}
function moveActor(a,dx,dz){const r=a===game?.p?(game.driving?1.5:game.prone?.85:.38):.38;const lift=a===game?.p?(game.p.y||0):0,height=(a===game?.p?(game.prone?.65:game.crouch?1.25:1.8):1.8)+lift;const step=a===game?.p?lift+.35:.1;if(!solid(a.x+dx,a.z,r,height,step))a.x+=dx;if(!solid(a.x,a.z+dz,r,height,step))a.z+=dz}
function rayBox(origin,dir,b){let lo=0,hi=300;const min=[b.x-b.w/2,b.y||0,b.z-b.d/2],max=[b.x+b.w/2,(b.y||0)+b.h,b.z+b.d/2];for(let i=0;i<3;i++){if(Math.abs(dir[i])<1e-7){if(origin[i]<min[i]||origin[i]>max[i])return Infinity;}else{let a=(min[i]-origin[i])/dir[i],c=(max[i]-origin[i])/dir[i];if(a>c)[a,c]=[c,a];lo=Math.max(lo,a);hi=Math.min(hi,c);if(lo>hi)return Infinity}}return lo}
function obstruction(o,d){let nearest=300;if(indiaWorld()){for(const b of window.AkrivaIndia.blocks)nearest=Math.min(nearest,rayBox(o,d,b));return nearest;}for(const a of covers){if(rayBox(o,d,a.bounds||a)>nearest)continue;if(a.parts){for(const part of a.parts)nearest=Math.min(nearest,rayBox(o,d,part));}else nearest=Math.min(nearest,rayBox(o,d,a));}return nearest;}
function raySphere(o,d,p,r){const v=o.map((a,i)=>a-p[i]),b=dot(v,d),c=dot(v,v)-r*r,disc=b*b-c;if(disc<0)return Infinity;const t=-b-Math.sqrt(disc);return t>0?t:Infinity}
function reload(){if(game?.mode==='squad104'){window.Akriva104.command('reload');return;}if(!game||game.phase!=='playing'||game.reload>0||game.mag===WEAPONS[game.weapon].mag||game.reserve<=0)return;game.reload=WEAPONS[game.weapon].reload;combatAudio('reload');note('Reloading…',game.reload);hud()}
function rewardKill(b){game.kills++;game.credits+=150;if(game.mode==='squad'||game.mode==='coop')game.score.blue++;dropWeapon(b);feed('You ⟶ '+(b.name||'Hostile'));note('ELIMINATED · +150 credits'+(b.weapon&&b.weapon!=='ranger'?' · '+WEAPONS[b.weapon].name+' dropped':''));}
// Q / Gun button cycles through guns already carried (bought or picked up).
function ownedWeapons(){return Object.keys(WEAPONS).filter(id=>id===game.weapon||game.inventory[id]);}
function cycleWeapon(){if(!game||game.phase!=='playing')return;const owned=ownedWeapons();if(owned.length<2){note('Only one gun · pick up another from the ground');return;}switchWeapon(owned[(owned.indexOf(game.weapon)+1)%owned.length]);}
function dropWeapon(v){game.loot.push(v.weapon&&v.weapon!=='ranger'?{x:v.x,z:v.z,type:'weapon',weapon:v.weapon,taken:false}:{x:v.x,z:v.z,type:'ammo',taken:false});}
function switchWeapon(id){if(game?.mode==='squad104'){window.Akriva104.command('weapon',{weapon:id});return;}if(!WEAPONS[id])return;if(!game){equipment.weapon=id;return;}if(game.phase!=='playing'){ $('weapon-select').value=game.weapon;return;}if(!game.inventory[id]){if(game.credits<WEAPONS[id].cost){note('Not enough credits for '+WEAPONS[id].name);$('weapon-select').value=game.weapon;return;}game.credits-=WEAPONS[id].cost;game.inventory[id]={mag:WEAPONS[id].mag,reserve:WEAPONS[id].reserve};}game.inventory[game.weapon]={mag:game.mag,reserve:game.reserve};game.weapon=id;game.mag=game.inventory[id].mag;game.reserve=game.inventory[id].reserve;game.reload=0;game.cooldown=.25;$('weapon-select').value=id;note(WEAPONS[id].name+' equipped');hud();}
function fire(){if(game?.mode==='squad104'){if(game.driving)return;window.Akriva104.fire();return;}if(!game||game.phase!=='playing'||game.p.hp<=0||game.driving||game.cooldown>0||game.reload>0)return;if(game.mag<=0){reload();return;}const w=WEAPONS[game.weapon];game.mag--;game.cooldown=w.rate;game.muzzle=.055;game.noise={kind:'shot',x:game.p.x,z:game.p.z,time:game.time,radius:game.weapon==='sniper'?70:45};game.kick=Math.min(.3,(game.kick||0)+w.recoil*9);combatAudio('shot');const o=[game.p.x,eyeHeight(),game.p.z];let dir=direction();if(viewMode==='tps'){const cam=cameraState();let dist=Math.min(w.range,obstruction(cam.eye,cam.dir));for(const b of game.bots)if(b.hp>0&&b.team!=='blue')dist=Math.min(dist,raySphere(cam.eye,cam.dir,[b.x,1.05,b.z],.28),raySphere(cam.eye,cam.dir,[b.x,1.52,b.z],.16));for(const r of hostileRemotes())dist=Math.min(dist,raySphere(cam.eye,cam.dir,[r.x,r.y+1.05,r.z],.28),raySphere(cam.eye,cam.dir,[r.x,r.y+1.52,r.z],.16));const aim=cam.eye.map((v,i)=>v+cam.dir[i]*dist);dir=norm(aim.map((v,i)=>v-o[i]));}for(let pellet=0;pellet<w.pellets;pellet++){game.shotsFired++;const d=w.pellets===1?dir:norm(dir.map(v=>v+(Math.random()-.5)*.045));let nearest=Math.min(w.range,obstruction(o,d)),victim=null,head=false;for(const b of game.bots){if(b.hp<=0||b.team==='blue')continue;const body=raySphere(o,d,[b.x,1.05,b.z],.28),top=raySphere(o,d,[b.x,1.52,b.z],.16),hit=Math.min(body,top);if(hit<nearest){nearest=hit;victim=b;head=top<body;}}for(const r of hostileRemotes()){const body=raySphere(o,d,[r.x,r.y+1.05,r.z],.28),top=raySphere(o,d,[r.x,r.y+1.52,r.z],.16),hit=Math.min(body,top);if(hit<nearest){nearest=hit;victim=r;head=top<body;}}if(victim){game.shotsHit++;if(head)game.headshots++;}if(victim?.remote){net.ph.push([++net.seq,victim.remote,head?w.head:w.damage]);game.hit=.12;combatAudio('hit');if(head)note('HEADSHOT',.6);}else if(victim){const dealt=head?w.head:w.damage;if(coopClient())net.hits.push([++net.seq,victim.id,dealt]);else victim.hp=Math.max(0,victim.hp-dealt);victim.alert={x:game.p.x,z:game.p.z,time:game.time};game.hit=.12;combatAudio('hit');if(victim.hp===0&&!coopClient())rewardKill(victim);else if(head)note('HEADSHOT',.6);}const endPoint=o.map((v,i)=>v+d[i]*nearest);if(!victim&&nearest<w.range-.01){game.impacts.push({p:endPoint.map((v,i)=>v-d[i]*.025),life:7,age:0});if(game.impacts.length>24)game.impacts.shift();}game.shots.push({a:viewMode==='fps'?weaponPose().muzzle:o,b:endPoint,life:.035,player:true});if(game.mode==='coop')net.shot=[++net.seq,...o,...endPoint].map((v,i)=>i?+v.toFixed(2):v);}pitch=Math.min(.9,pitch+w.recoil);if(game.mag===0&&game.reserve>0)reload();hud();}
function launchMissile(){if(game?.mode==='squad104'){note('Missiles are unavailable in Squad 104');return;}if(!game||game.phase!=='playing'||game.driving||game.missiles<=0){if(game?.phase==='playing')note('No missiles available in this loadout');return;}game.missiles--;const cam=cameraState(),dist=Math.min(100,obstruction(cam.eye,cam.dir)),aim=cam.eye.map((v,i)=>v+cam.dir[i]*dist),p=[game.p.x,eyeHeight()-.05,game.p.z],d=norm(aim.map((v,i)=>v-p[i]));game.projectiles.push({p,d,life:3,heavy:game.missileType==='heavy'});note('MISSILE AWAY');hud();}
function explode(p,heavy){game.noise={kind:'blast',x:p[0],z:p[2],time:game.time,radius:90};const radius=heavy?11:7,damage=heavy?160:110;game.explosions.push({p:[...p],life:.65,radius});for(const r of hostileRemotes()){const delta=[r.x-p[0],r.y+1.1-p[1],r.z-p[2]],dist=Math.hypot(...delta);if(dist<radius&&(dist<.1||obstruction(p,delta.map(v=>v/dist))>=dist-.35))net.ph.push([++net.seq,r.remote,Math.round(damage*(1-dist/radius))]);}for(const b of game.bots){if(b.hp<=0||b.team==='blue')continue;const delta=[b.x-p[0],1.1-p[1],b.z-p[2]],dist=Math.hypot(...delta);if(dist<radius&&(dist<.1||obstruction(p,delta.map(v=>v/dist))>=dist-.35)){const dealt=damage*(1-dist/radius);if(coopClient()){net.hits.push([++net.seq,b.id,Math.round(dealt)]);continue;}const hp=b.hp;b.hp=Math.max(0,b.hp-dealt);if(hp>0&&b.hp===0)rewardKill(b);}}}
function callAmbulance(){if(game?.mode==='squad104'){note('Ambulances are parked at city hubs. Move nearby and press V to drive');return;}if(!game||game.phase!=='playing')return;if(game.ambulance){note('Ambulance deployed · '+Math.round(Math.hypot(game.p.x-game.ambulance.x,game.p.z-game.ambulance.z))+'m away. V to enter nearby.');return;}if(game.ambulanceType==='none'){note('Choose ambulance support before deployment');return;}for(let a=0;a<12;a++){const angle=yaw+a*Math.PI/6,x=game.p.x+Math.sin(angle)*6,z=game.p.z-Math.cos(angle)*6;if(!solid(x,z,2.5)){game.ambulance={type:'ambulance',x,z,heading:angle,speed:0,roll:0};note('AMBULANCE READY · V nearby to drive. Heals while parked nearby.');hud();return;}}note('No clear parking space. Move into an open area.');}
function nearestVehicle(){if(!game)return null;return [...(game.vehicles||[]),...(game.ambulance?[game.ambulance]:[])].filter(v=>(!v.driver||v.driver===window.Akriva104?.id)&&Math.hypot(v.x-game.p.x,v.z-game.p.z)<4).sort((a,b)=>Math.hypot(a.x-game.p.x,a.z-game.p.z)-Math.hypot(b.x-game.p.x,b.z-game.p.z))[0]||null;}
function enterVehicle(){if(game?.mode==='squad104'){window.Akriva104.command('vehicle');return;}if(!game||game.phase!=='playing'||!onGround())return;if(game.driving){const v=game.activeVehicle;let exit=null;for(const off of[2.8,-2.8,3.5,-3.5,5,-5]){const heading=v?.heading||0,x=game.p.x+Math.cos(heading)*off,z=game.p.z+Math.sin(heading)*off;if(!solid(x,z,.4)){exit={x,z};break;}}if(!exit){note('Exit blocked · park in open space');return;}if(v)v.speed=0;game.driving=false;game.activeVehicle=null;Object.assign(game.p,exit);note('Exited vehicle');}else{const v=nearestVehicle();if(!v){note('Move within 4m of a vehicle, then press V / Drive');return;}game.driving=true;game.activeVehicle=v;game.crouch=false;game.prone=false;game.p.y=0;game.p.vy=0;$('prone').textContent='Prone · Z';$('prone').setAttribute('aria-pressed','false');$('crouch').textContent='Crouch · C';$('crouch').setAttribute('aria-pressed','false');viewMode='tps';$('view-mode').textContent='Third person · TPP';game.p.x=v.x;game.p.z=v.z;yaw=v.heading;note('Driving '+(window.AkrivaIndia?.types[v.type]?.name||'ambulance')+' · W/S throttle · A/D steer · Space brake · V exit',5);}hud();}
function driveVehicle(dt,steer,throttle){const v=game.activeVehicle;if(!v)return;const india=window.AkrivaIndia;if(!india)return;if(keys.has('brake'))v.speed=(v.speed||0)*Math.exp(-dt*10);india.drive(v,keys.has('brake')?0:throttle,steer,dt,(x,z,r)=>solid(x,z,r,2.0));game.p.x=v.x;game.p.z=v.z;yaw+=Math.atan2(Math.sin(v.heading-yaw),Math.cos(v.heading-yaw))*Math.min(1,dt*2);}
function indiaStatus(){if(game?.mode!=='india')return;const india=window.AkrivaIndia,c=india.nearest(game.p.x,game.p.z);if(Math.hypot(c.x-game.p.x,c.z-game.p.z)<28&&!game.visited.includes(c.id)){game.visited.push(c.id);note('REGION DISCOVERED · '+c.region,3);}ui('zone-text','textContent','INDIA EXPEDITION · '+game.visited.length+'/36 REGIONS');ui('compass','textContent',c.region.toUpperCase()+' · '+c.name+' · '+Math.round(Math.hypot(c.x-game.p.x,c.z-game.p.z))+'m');if(game.driving){const v=game.activeVehicle;ui('weapon-name','textContent',(india.types[v.type]?.name||'AMBULANCE').toUpperCase());ui('weapon-state','textContent',Math.round(Math.abs(v.speed||0)*3.6)+' KM/H · V EXIT');}}
let atlasResume=false;
function closeIndiaAtlas(){ $('india-atlas').close();if(atlasResume&&game?.phase==='paused')pause();atlasResume=false;}
function openIndiaAtlas(){if(game?.mode!=='india'){note('Choose India Expedition in the Operations Hub to open the national atlas');return;}atlasResume=game.phase==='playing';if(atlasResume)pause();$('india-atlas').showModal();const c=$('india-atlas-canvas').getContext('2d');if(c)window.AkrivaIndia.atlas(c,600,600,game.p);}
function travelIndia(){if(game?.mode!=='india')return;const c=window.AkrivaIndia.cities[Number($('india-destination').value)];if(!c)return;game.driving=false;if(game.activeVehicle)game.activeVehicle.speed=0;game.activeVehicle=null;Object.assign(game.p,{x:c.x,z:c.z,y:0,vy:0});game.vehicles=window.AkrivaIndia.fleet(c.x,c.z);yaw=0;closeIndiaAtlas();note('TRANSIT ARRIVAL · '+c.name+' / '+c.region+' · vehicles parked ahead',5);hud();}

function useMedkit(){if(game?.mode==='squad104'){window.Akriva104.command('medkit');return;}if(!game||game.phase!=='playing'||game.medkits<=0||game.p.hp>=100)return;game.medkits--;game.p.hp=Math.min(100,game.p.hp+60);note('MEDKIT · +60 health');hud();}
function damagePlayer(amount){if(game.time<(game.p.protUntil||0))return;const reduction=game.driving&&game.activeVehicle===game.ambulance&&game.ambulanceType==='armored'?.5:0,blocked=Math.min(game.armor,amount*.4);game.armor-=blocked;game.p.hp=Math.max(0,game.p.hp-(amount-blocked)*(1-reduction));if(game.p.hp===0&&game.mode==='squad'&&!game.scoredDeath){game.scoredDeath=true;game.score.red++;}game.damageFlash=.25;}

function collect(){if(game?.mode==='squad104'){window.Akriva104.command('supply');return;}if(!game||game.phase!=='playing')return;let found=false;for(const l of game.loot){if(l.taken||Math.hypot(l.x-game.p.x,l.z-game.p.z)>2.7||Math.abs((l.y||0)-(game.p.y||0))>1.6)continue;if(l.type==='med'&&game.p.hp>=100)continue;l.taken=true;found=true;if(l.type==='weapon'){const w=WEAPONS[l.weapon],extra=w.mag*2;if(game.weapon===l.weapon){game.reserve+=extra;note('+'+extra+' '+w.name.toUpperCase()+' AMMO');}else if(game.inventory[l.weapon]){game.inventory[l.weapon].reserve+=extra;note('+'+extra+' '+w.name.toUpperCase()+' AMMO');}else{game.inventory[l.weapon]={mag:w.mag,reserve:extra};switchWeapon(l.weapon);note(w.name.toUpperCase()+' PICKED UP · Q to switch guns',3);}}else if(l.type==='ammo'){game.reserve+=60;note('+60 AMMO');}else{game.p.hp=Math.min(100,game.p.hp+45);note('+45 HEALTH');}beep(600);break}if(!found)note('Move near a gun, ammo or green medical crate, then press E.');hud()}
function ui(id,prop,value){const key=id+':'+prop;if(hudCache.get(key)===value)return;hudCache.set(key,value);$(id)[prop]=value}
function buildingLabel(){const inside=covers.find(a=>a.enterable&&Math.abs(game.p.x-a.x)<a.w/2&&Math.abs(game.p.z-a.z)<a.d/2);if(!inside)return '';const level=Math.floor(((game.p.y||0)+.5)/(inside.kind==='warehouse'?3.4:3.2));return inside.kind==='apartment'?(level>=inside.floors?'APARTMENT ROOF':level?'APARTMENT · FLOOR '+level:'APARTMENT · GROUND FLOOR'):level?'WAREHOUSE MEZZANINE':'WAREHOUSE INTERIOR';}
function scoreboardHtml(){if(onlinePvp())return pvpBoard();const row=(name,kills,hp,you)=>'<tr'+(hp>0?'':' class="down"')+'><td>'+(you?'<b>'+escapeHtml(name)+'</b>':escapeHtml(name))+'</td><td>'+kills+'</td><td>'+(hp>0?Math.ceil(hp)+' HP':'DOWN')+'</td></tr>',team=t=>game.bots.filter(b=>b.team===t);
 return '<div class="board-head"><span class="blue">BLUE '+game.score.blue+'</span><span>'+(game.mode==='coop'?'ONLINE CO-OP':'SQUAD BATTLE')+'</span><span class="red">'+game.score.red+' RED</span></div><div class="board-teams"><table class="blue"><tr><th>Blue squad</th><th>K</th><th></th></tr>'+row(game.mode==='coop'?coopName+' (you)':'You',game.kills,game.p.hp,true)+team('blue').map(b=>row(b.name,b.kills||0,b.hp)).join('')+[...net.remote.values()].filter(()=>game.mode==='coop').map(r=>row(r.name,r.kills,r.hp)).join('')+'</table><table class="red"><tr><th>Red squad</th><th>K</th><th></th></tr>'+team('red').map(b=>row(b.name,b.kills||0,b.hp)).join('')+'</table></div>';}
let boardOpen=false,boardAge=0;const scoreboard=document.createElement('div'),teamBar=document.createElement('button');scoreboard.id='scoreboard';scoreboard.hidden=true;teamBar.id='team-bar';teamBar.hidden=true;teamBar.onclick=()=>{boardOpen=!boardOpen;hud();};document.body.append(scoreboard,teamBar);
